WITH RECURSIVE routes(destination_id,visited,path,hops,total_minutes) AS (SELECT 1::BIGINT,[1::BIGINT],'1'::VARCHAR,0::BIGINT,0::BIGINT UNION ALL SELECT e.to_id,list_append(r.visited,e.to_id),r.path||'>'||e.to_id::VARCHAR,(r.hops+1)::BIGINT,(r.total_minutes+e.minutes)::BIGINT FROM routes r JOIN route_edges e ON e.from_id=r.destination_id WHERE r.hops<2 AND NOT list_contains(r.visited,e.to_id)) SELECT destination_id,path,hops,total_minutes FROM routes WHERE hops BETWEEN 1 AND 3 ORDER BY destination_id,path;
